    public MyControl()
    {
        _statusStrip = new StatusStrip();
        // .NET 9 breaking change: StatusStrip rendering default changed.
        // Explicitly set the render mode to preserve .NET 8 behavior.
        _statusStrip.RenderMode = ToolStripRenderMode.System;
        Controls.Add(_statusStrip);
    }

    /// <summary>
    /// Demonstrates safe usage of DropDownControl after .NET 9 breaking change:
    /// passing null now throws ArgumentNullException.
    /// </summary>
    public static void ShowDropDown(IWindowsFormsEditorService editorService, Control control)
    {
        // .NET 9 breaking change: DropDownControl(null) throws ArgumentNullException
        if (control == null)
            return;

        editorService.DropDownControl(control);
    }
}

